#!/usr/bin/env python3
"""Record exact, reviewable language changes against the frozen R2 text inventory."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'tools/candidates/remaining-batch-r3-20261018'
BASE.mkdir(exist_ok=True,parents=True)
AUDIT=Path('/tmp/mb-r3/audit')
edits=[]
def add(sku,prefix,changes):
    files=json.loads((AUDIT/(sku+'.json')).read_text())
    f=next(f for f in files if f['file'].startswith(prefix))
    rows={r['loc']:r['text'] for r in f['rows']}
    for loc,new in changes.items():
        if isinstance(loc,int):loc='word/document.xml:p'+str(loc)
        assert loc in rows,(sku,f['file'],loc)
        edits.append({'sku':sku,'file':f['file'],'loc':loc,'old':rows[loc],'new':new})
