known={(e['sku'],e['file'],e['loc']) for e in edits}
for sku in ['P1','P2','P4','P7','P8','P9','P10','P13']:
 for f in json.loads((AUDIT/(sku+'.json')).read_text()):
  if f['file'].endswith('.pdf'):continue
  for r in f['rows']:
   k=(sku,f['file'],r['loc'])
   if k not in known and r['text'] in generic:
    edits.append({'sku':sku,'file':f['file'],'loc':r['loc'],'old':r['text'],'new':generic[r['text']]});known.add(k)
(BASE/'text-edits.json').write_text(json.dumps(edits,ensure_ascii=False,indent=2)+'\n')
print('EXACT_TEXT_EDITS',len(edits))
